+	require.Equal(t, 10, promptTotal)
+	require.Equal(t, 10, completionTotal)
+	require.Equal(t, 6, streaming.TokenCount())
+	require.Error(t, streaming.Add())
+	promptTotal, completionTotal = usage.CountAll()
+	require.Equal(t, 10, promptTotal)
+	require.Equal(t, 10, completionTotal)
+}
